import { Hono } from "hono"

import type { Env, Variables } from "../env"
import { getDb } from "../lib/db"
import { optionalAuth, rateLimitUnauthenticated } from "../lib/middleware"
import { checkRepoAccess, requiredParam } from "./cache"

const overviewRoutes = new Hono<{ Bindings: Env; Variables: Variables }>()

function parseDateParam(value: string | undefined): string | undefined {
  if (!value) return undefined
  const d = new Date(value)
  if (isNaN(d.getTime())) return undefined
  return value
}

function parseTimeZoneParam(value: string | undefined): string | undefined {
  if (!value) return undefined
  try {
    new Intl.DateTimeFormat("en-US", { timeZone: value })
    return value
  } catch {
    return undefined
  }
}

// GET /:org/:repo/overview/commit-stats?since=...&until=...
overviewRoutes.get(
  "/:org/:repo/overview/commit-stats",
  optionalAuth,
  rateLimitUnauthenticated,
  async (c) => {
    const userId = c.get("userId") as string | undefined
    const org = requiredParam(c, "org")
    const repo = requiredParam(c, "repo")
    const repoFullName = `${org}/${repo}`
    const since = parseDateParam(c.req.query("since"))
    const until = parseDateParam(c.req.query("until"))
    const db = getDb(c.env)

    const repoAccess = await checkRepoAccess(db, repoFullName, userId)
    if (repoAccess instanceof Response) return repoAccess
    if (!repoAccess) return c.json({ error: "Repository not found" }, 404)

    const branch = repoAccess.default_branch ?? "main"

    const stats = await db.repoOverview.getCommitStats(repoAccess.id, branch, since, until)

    return c.json({
      total: stats.total,
      with_checkpoint: stats.withCheckpoint,
      without_checkpoint: stats.total - stats.withCheckpoint,
      daily: stats.daily.map((d) => ({
        date: d.date,
        count: d.count,
        with_checkpoint: d.withCheckpoint,
      })),
      branch,
      since: since ?? null,
      until: until ?? null,
    })
  },
)

// GET /:org/:repo/overview/contributors?since=...&until=...
overviewRoutes.get(
  "/:org/:repo/overview/contributors",
  optionalAuth,
  rateLimitUnauthenticated,
  async (c) => {
    const userId = c.get("userId") as string | undefined
    const org = requiredParam(c, "org")
    const repo = requiredParam(c, "repo")
    const repoFullName = `${org}/${repo}`
    const since = parseDateParam(c.req.query("since"))
    const until = parseDateParam(c.req.query("until"))
    const db = getDb(c.env)

    const repoAccess = await checkRepoAccess(db, repoFullName, userId)
    if (repoAccess instanceof Response) return repoAccess
    if (!repoAccess) return c.json({ error: "Repository not found" }, 404)

    const branch = repoAccess.default_branch ?? "main"

    const result = await db.repoOverview.getContributorsForBranch(
      repoAccess.id,
      branch,
      since,
      until,
    )

    return c.json({
      total_contributors: result.totalContributors,
      top_contributors: result.topContributors.map((contributor) => ({
        username: contributor.username,
        github_id: contributor.githubId,
        commit_count: contributor.commitCount,
      })),
      daily: result.daily,
      branch,
      since: since ?? null,
      until: until ?? null,
    })
  },
)

// GET /:org/:repo/overview/pr-stats?since=...&until=...
