export function computeStats(
  checkpoints: UserCheckpoint[],
  streaks: { currentStreak: number; streak: number } = { currentStreak: 0, streak: 0 },
): ContributionStats {
  if (checkpoints.length === 0) {
    return {
      tasks: 0,
      orchestration: 0,
      iteration: 0,
      throughput: 0,
      continuity: { hours: 0, ...streaks },
    }
  }

  // Use || instead of ?? because checkpoints always have agent involvement.
  // A value of 0 or null indicates a CLI error, so we default to 1.
  const totalSteps = checkpoints.reduce((sum, cp) => sum + (cp.steps || 1), 0)
  const count = checkpoints.length

  // orchestration = sum(steps) / (sum(steps) + count) * 100
  const orchestration = (totalSteps / (totalSteps + count)) * 100

  // iteration = avg(sessionCount)
  const totalSessionCount = checkpoints.reduce((sum, cp) => sum + (cp.session_count || 1), 0)
  const iteration = totalSessionCount / count

  // throughput = average total tokens per checkpoint (in thousands)
  const checkpointsWithTokens = checkpoints.filter(
    (cp) => cp.input_tokens != null || cp.output_tokens != null,
  )
  const totalTokens = checkpointsWithTokens.reduce(
    (sum, cp) => sum + (cp.input_tokens ?? 0) + (cp.output_tokens ?? 0),
    0,
  )
  const throughput =
    checkpointsWithTokens.length > 0 ? totalTokens / checkpointsWithTokens.length / 1000 : 0

  // continuity.hours = max(steps) * 2 / 60 (estimate: 2 min/step)
  const maxSteps = Math.max(...checkpoints.map((cp) => cp.steps || 1))
  const hours = (maxSteps * 2) / 60

  return {
    tasks: count,
    orchestration: Math.round(orchestration),
    iteration: Math.round(iteration * 10) / 10,
    throughput,
    continuity: {
      hours: Math.round(hours * 10) / 10,
      ...streaks,
    },
  }
}

