function buildPreambleUserPrompt(input: {
  transcriptTail: string
  previousChunkIndex: number
}): string {
  return `<transcript_tail chunk="${input.previousChunkIndex}">\n${escapePromptDelimiters(
    input.transcriptTail,
  )}\n</transcript_tail>`
}

export function buildMapUserPrompt(chunk: CheckpointAnalysisChunk): string {
  const preambleBlock = chunk.preamble
    ? `## Context from Previous Chunk\n\n<previous_context>\n${escapePromptDelimiters(
        chunk.preamble,
      )}\n</previous_context>\n\n`
    : ""

  return `${preambleBlock}## Transcript (Chunk ${chunk.index} of ${chunk.total_chunks})\n\n<transcript>\n${escapePromptDelimiters(
    chunk.transcript,
  )}\n</transcript>\n\nExtract the CheckpointExtraction JSON.`
}

function buildMergeUserPrompt(extractions: CheckpointExtraction[]): string {
  const extractionsBlock = extractions
    .map(
      (extraction, index) =>
        `<extraction chunk="${index + 1}">\n${escapePromptDelimiters(
          JSON.stringify(extraction),
        )}\n</extraction>`,
    )
    .join("\n\n")

  return `Here are ${extractions.length} extraction objects from sequential chunks of the same checkpoint.\n\n${extractionsBlock}\n\nMerge these into a single CheckpointExtraction JSON.`
}

