package stringutil

import (
	"fmt"
	"time"
)

// TimeAgo formats a time as a human-readable relative duration.
// Returns "just now" for durations under a minute, then "Nm ago",
// "Nh ago", or "Nd ago" respectively.
func TimeAgo(t time.Time) string {
	d := time.Since(t)
	switch {
	case d < time.Minute:
		return "just now"
	case d < time.Hour:
		return fmt.Sprintf("%dm ago", int(d.Minutes()))
	case d < 24*time.Hour:
		return fmt.Sprintf("%dh ago", int(d.Hours()))
	default:
		return fmt.Sprintf("%dd ago", int(d.Hours()/24))
	}
}
```

