package activity

import (
	"encoding/json"
	"errors"
	"os"
	"path"
	"path/filepath"
	"sort"
	"strings"
)

// FocusAreaRule maps a glob pattern to a human-readable label with a
// priority tiebreaker. Higher priority wins; longest match breaks ties.
type FocusAreaRule struct {
	Match    string `json:"match"`
	Label    string `json:"label"`
	Priority int    `json:"priority"`
}

// focusAreaConfig mirrors .entire/activity_areas.json.
type focusAreaConfig struct {
	Version int             `json:"version"`
	Areas   []FocusAreaRule `json:"areas"`
}

// BuiltInFocusAreaRules returns the shipped defaults for the entireio/cli repo.
// Users can override via .entire/activity_areas.json.
func BuiltInFocusAreaRules() []FocusAreaRule {
	return []FocusAreaRule{
		{"cmd/entire/cli/checkpoint/**", "checkpoint storage", 100},
		{"cmd/entire/cli/session/**", "session state", 100},
		{"cmd/entire/cli/strategy/**", "checkpoint strategy", 100},
		{"cmd/entire/cli/agent/**", "agent integrations", 100},
		{"cmd/entire/cli/search**", "search", 100},
		{"cmd/entire/cli/explain**", "explain", 100},
		{"cmd/entire/cli/status**", "status", 100},
		{"cmd/entire/cli/activity/**", "activity", 100},
		{"cmd/entire/cli/trail/**", "trails", 100},
		{"cmd/entire/cli/hooks**", "hooks", 100},
		{"cmd/entire/cli/integration_test/**", "integration tests", 100},
		{"e2e/**", "e2e", 100},
		{"docs/architecture/**", "architecture docs", 100},
		{"docs/**", "docs", 100},
	}
}

// LoadFocusAreaConfig reads .entire/activity_areas.json from the given
// worktree root. Returns an empty slice (no error) if the file is absent.
func LoadFocusAreaConfig(worktreeRoot string) ([]FocusAreaRule, error) {
	p := filepath.Join(worktreeRoot, ".entire", "activity_areas.json")
	data, err := os.ReadFile(p)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return nil, nil
		}
		return nil, err
	}
	var cfg focusAreaConfig
	if err := json.Unmarshal(data, &cfg); err != nil {
		return nil, err
	}
	return cfg.Areas, nil
}

// ResolveFocusArea maps a repo-relative path to a focus-area label,
// applying rule priority and longest-match tiebreak. Falls back to the
// first meaningful directory component if no rule matches.
func ResolveFocusArea(rules []FocusAreaRule, repoRelPath string) string {
	type match struct {
		label    string
		priority int
		length   int
	}
	var best *match
	for _, r := range rules {
		if !globMatch(r.Match, repoRelPath) {
			continue
		}
		m := match{label: r.Label, priority: r.Priority, length: len(r.Match)}
		if best == nil ||
			m.priority > best.priority ||
			(m.priority == best.priority && m.length > best.length) {
			cur := m
			best = &cur
		}
	}
	if best != nil {
		return best.label
	}
	return firstMeaningfulDir(repoRelPath)
}

// ResolveFocusAreas returns the top distinct focus-area labels across a
// set of files, preserving insertion order of first appearance.
func ResolveFocusAreas(rules []FocusAreaRule, files []string) []string {
	seen := map[string]bool{}
	out := []string{}
	for _, f := range files {
		area := ResolveFocusArea(rules, f)
		if area == "" || seen[area] {
			continue
		}
		seen[area] = true
		out = append(out, area)
	}
	sort.SliceStable(out, func(i, j int) bool { return out[i] < out[j] })
	return out
}

// globMatch is a simple ** / * / literal matcher. "**" matches any
// number of path segments including zero. "*" matches within a segment.
func globMatch(pattern, p string) bool {
	pattern = strings.ReplaceAll(pattern, "**", "\x00")
	pattern = strings.ReplaceAll(pattern, "*", "[^/]*")
	pattern = strings.ReplaceAll(pattern, "\x00", ".*")
	ok, err := path.Match(convertToPathMatch(pattern), p)
	if err != nil || !ok {
		// Fall back to prefix match for "prefix/**" style rules.
		base := strings.TrimSuffix(strings.TrimSuffix(pattern, ".*"), "/")
		return strings.HasPrefix(p, base)
	}
	return ok
}

// convertToPathMatch adapts our simplified glob to Go's path.Match syntax.
func convertToPathMatch(pattern string) string {
	// path.Match supports ? * [ ] only - our "[^/]*" won't work, so we
	// collapse to * for single-segment wildcards. Good enough for our
	// prefix-style rules.
	return strings.ReplaceAll(pattern, "[^/]*", "*")
}

// firstMeaningfulDir returns the first non-trivial directory component
// of a repo-relative path, used as the focus-area fallback.
func firstMeaningfulDir(p string) string {
	parts := strings.Split(filepath.ToSlash(p), "/")
	for _, seg := range parts {
		if seg == "" || seg == "." || seg == ".." {
			continue
		}
		return seg
	}
	return ""
}
