package activity

import (
	"context"
	"fmt"

	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/session"
	"github.com/entireio/cli/cmd/entire/cli/strategy"
)

// Scope selects how much of the activity graph to read.
type Scope int

const (
	// ScopeCurrent loads sessions for the current repo only.
	ScopeCurrent Scope = iota
	// ScopeLocal is equivalent to ScopeCurrent but never calls the api.
	ScopeLocal
	// ScopeAll loads sessions across every repo the user has api access to.
	// Requires a login token.
	ScopeAll
)

// LoadOpts controls LoadActivity behavior.
type LoadOpts struct {
	Scope       Scope
	EnrichFromAPI bool
	InsecureHTTP  bool
}

func (o *LoadOpts) applyDefaults() {
	if o.Scope == 0 {
		o.Scope = ScopeCurrent
	}
}

// Activity is the full projection returned by LoadActivity. Read-only.
type Activity struct {
	Sessions []ActivitySession
	Source   DataSource
}

// LoadActivity projects sessions + checkpoints into ActivitySession values
// using local session state and committed checkpoint metadata. API
// enrichment happens only when opts.EnrichFromAPI is true and a token
// is available; it never blocks the local result.
func LoadActivity(ctx context.Context, opts LoadOpts) (*Activity, error) {
	opts.applyDefaults()

	worktreeRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		return nil, fmt.Errorf("worktree root: %w", err)
	}

	states, err := strategy.ListSessionStates(ctx)
	if err != nil {
		return nil, fmt.Errorf("list session states: %w", err)
	}

	rules := append(BuiltInFocusAreaRules())
	if repoLocal, err := LoadFocusAreaConfig(worktreeRoot); err == nil {
		rules = append(repoLocal, rules...)
	}

	out := &Activity{Source: SourceLocal}
	for _, s := range states {
		out.Sessions = append(out.Sessions, projectSession(s, rules))
	}
	return out, nil
}

// projectSession turns a session.State into an ActivitySession projection.
// No i/o; safe to unit-test with in-memory fixtures.
func projectSession(s *strategy.SessionState, rules []FocusAreaRule) ActivitySession {
	out := ActivitySession{
		SessionID:       s.SessionID,
		BaseCommit:      s.BaseCommit,
		WorktreeID:      s.WorktreeID,
		WorktreePath:    s.WorktreePath,
		StartedAt:       s.StartedAt,
		EndedAt:         s.EndedAt,
		Phase:           session.Phase(s.Phase),
		FilesTouched:    append([]string(nil), s.FilesTouched...),
		FocusAreas:      ResolveFocusAreas(rules, s.FilesTouched),
		IsActive:        s.EndedAt == nil,
		Source:          SourceLocal,
	}
	if s.LastInteractionTime != nil {
		out.LastInteraction = *s.LastInteractionTime
	}
	return out
}
