```go
package activity

import (
	"context"
	"os/exec"
	"regexp"
	"strings"
)

// LookupLinkedCommits returns a map from checkpoint ID to the list of
// commit SHAs on the active branch whose message contains a matching
// Entire-Checkpoint trailer. Unknown checkpoint IDs yield empty slices.
func LookupLinkedCommits(ctx context.Context, checkpointIDs []string) (map[string][]string, error) {
	out := map[string][]string{}
	for _, id := range checkpointIDs {
		out[id] = nil
	}
	// Use `git log` rather than go-git to leverage existing pager-free
	// formatting. We only need SHA + subject + body.
	cmd := exec.CommandContext(ctx, "git", "log", "--pretty=format:%H%n%B%n--ENTIRE-END--")
	data, err := cmd.Output()
	if err != nil {
		return out, nil // empty repo or no commits is fine
	}
	entries := strings.Split(string(data), "--ENTIRE-END--\n")
	trailerRe := regexp.MustCompile(`(?m)^Entire-Checkpoint:\s*([a-f0-9]+)\s*$`)
	for _, entry := range entries {
		entry = strings.TrimSpace(entry)
		if entry == "" {
			continue
		}
		lines := strings.SplitN(entry, "\n", 2)
		sha := strings.TrimSpace(lines[0])
		body := ""
		if len(lines) > 1 {
			body = lines[1]
		}
		matches := trailerRe.FindAllStringSubmatch(body, -1)
		for _, m := range matches {
			id := m[1]
			if _, ok := out[id]; ok {
				out[id] = append(out[id], sha)
			}
		}
	}
	return out, nil
}
```

