// number of path segments including zero. "*" matches within a segment.
func globMatch(pattern, p string) bool {
	pattern = strings.ReplaceAll(pattern, "**", "\x00")
	pattern = strings.ReplaceAll(pattern, "*", "[^/]*")
	pattern = strings.ReplaceAll(pattern, "\x00", ".*")
	ok, err := path.Match(convertToPathMatch(pattern), p)
	if err != nil || !ok {
		// Fall back to prefix match for "prefix/**" style rules.
		base := strings.TrimSuffix(strings.TrimSuffix(pattern, ".*"), "/")
		return strings.HasPrefix(p, base)
	}
	return ok
}

// convertToPathMatch adapts our simplified glob to Go's path.Match syntax.
func convertToPathMatch(pattern string) string {
	// path.Match supports ? * [ ] only - our "[^/]*" won't work, so we
	// collapse to * for single-segment wildcards. Good enough for our
	// prefix-style rules.
	return strings.ReplaceAll(pattern, "[^/]*", "*")
}

