// globMatch implements prefix-only pattern matching for v1. Patterns
// ending in "**" or "*" match any path starting with the literal prefix.
// Full glob semantics (intra-segment wildcards, brace expansion, etc.)
// are out of scope for v1 — document this clearly so custom rule
// authors know what's supported.
//
// Supported:
//
//   "cmd/entire/cli/checkpoint/**"  -> prefix match "cmd/entire/cli/checkpoint/"
//   "cmd/entire/cli/search**"       -> prefix match "cmd/entire/cli/search"
//   "docs/**"                        -> prefix match "docs/"
//
// Not supported in v1 (would silently prefix-match):
//
//   "**/*.go", "cmd/*/cli/**"
//
// A future version may adopt github.com/bmatcuk/doublestar for full glob.
func globMatch(pattern, p string) bool {
	prefix := strings.TrimSuffix(strings.TrimSuffix(pattern, "**"), "*")
	prefix = strings.TrimSuffix(prefix, "/")
	if prefix == "" {
		return true // "**" alone matches everything
	}
	// Exact match OR path under that prefix directory.
	return p == prefix || strings.HasPrefix(p, prefix+"/") || strings.HasPrefix(p, prefix)
}

