```go
// testutil_test.go additions
import (
	"bytes"
	"encoding/json"
	"os/exec"

	gogit "github.com/go-git/go-git/v6"
	"github.com/go-git/go-git/v6/plumbing"
	"github.com/go-git/go-git/v6/plumbing/object"

	"github.com/entireio/cli/cmd/entire/cli/checkpoint/id"
	"github.com/entireio/cli/cmd/entire/cli/strategy"
)

type committedFixture struct {
	ID        string
	SessionID string
	CreatedAt time.Time
	Files     []string
}

// writeCommittedCheckpoint writes a minimal metadata.json entry onto the
// entire/checkpoints/v1 branch at the sharded path <id[:2]>/<id[2:]>/metadata.json.
// The shape matches what strategy.ReadCheckpointMetadata consumes in common.go.
func writeCommittedCheckpoint(t *testing.T, repoRoot string, f committedFixture) {
	t.Helper()
	repo, err := gogit.PlainOpen(repoRoot)
	if err != nil {
		t.Fatalf("open repo: %v", err)
	}

	// Build a CheckpointInfo stub; encode as metadata.json.
	info := strategy.CheckpointInfo{
		CheckpointID: id.CheckpointID(f.ID),
		SessionID:    f.SessionID,
		CreatedAt:    f.CreatedAt,
		FilesTouched: f.Files,
	}
	body, err := json.MarshalIndent(info, "", "  ")
	if err != nil {
		t.Fatal(err)
	}

	// Write the blob.
	blobHash, err := repo.Storer.SetEncodedObject(makeBlob(t, body))
	if err != nil {
		t.Fatalf("store blob: %v", err)
	}

	// Build a tree for <id[2:]>/metadata.json
	leafTree := object.Tree{
		Entries: []object.TreeEntry{
			{Name: "metadata.json", Mode: 0o100644, Hash: blobHash},
		},
	}
	leafHash := storeTree(t, repo, &leafTree)

	// Build shard tree for <id[:2]>/<id[2:]>
	shardTree := object.Tree{
		Entries: []object.TreeEntry{
			{Name: f.ID[2:], Mode: 0o040000, Hash: leafHash},
		},
	}
	shardHash := storeTree(t, repo, &shardTree)

	// Build root tree
	rootTree := object.Tree{
		Entries: []object.TreeEntry{
			{Name: f.ID[:2], Mode: 0o040000, Hash: shardHash},
		},
	}
	rootHash := storeTree(t, repo, &rootTree)

	// Create a commit on entire/checkpoints/v1.
	//
	// Use the git CLI to avoid go-git's reset-with-ignored-dir bug.
	// We commit an empty tree via plumbing and then update the ref.
	commit := &object.Commit{
		Author:    object.Signature{Name: "test", Email: "test@example.com", When: f.CreatedAt},
		Committer: object.Signature{Name: "test", Email: "test@example.com", When: f.CreatedAt},
		Message:   "Checkpoint: " + f.ID,
		TreeHash:  rootHash,
	}
	commitHash := storeCommit(t, repo, commit)

	// Force-update the branch ref using the git CLI (safe ref op).
	cmd := exec.Command("git", "update-ref", "refs/heads/entire/checkpoints/v1", commitHash.String())
	cmd.Dir = repoRoot
	if out, err := cmd.CombinedOutput(); err != nil {
		t.Fatalf("update-ref: %v\n%s", err, out)
	}
}

// makeBlob encodes bytes as a git blob object ready to be stored.
func makeBlob(t *testing.T, data []byte) plumbing.EncodedObject {
	t.Helper()
	obj := plumbing.MemoryObject{}
	obj.SetType(plumbing.BlobObject)
	obj.SetSize(int64(len(data)))
	w, err := obj.Writer()
	if err != nil {
		t.Fatal(err)
	}
	if _, err := bytes.NewReader(data).WriteTo(w); err != nil {
		t.Fatal(err)
	}
	w.Close()
	return &obj
}

// storeTree encodes and stores a tree object, returning its hash.
func storeTree(t *testing.T, repo *gogit.Repository, tree *object.Tree) plumbing.Hash {
	t.Helper()
	obj := repo.Storer.NewEncodedObject()
	if err := tree.Encode(obj); err != nil {
		t.Fatal(err)
	}
	h, err := repo.Storer.SetEncodedObject(obj)
	if err != nil {
		t.Fatal(err)
	}
	return h
}

// storeCommit encodes and stores a commit object, returning its hash.
func storeCommit(t *testing.T, repo *gogit.Repository, commit *object.Commit) plumbing.Hash {
	t.Helper()
	obj := repo.Storer.NewEncodedObject()
	if err := commit.Encode(obj); err != nil {
		t.Fatal(err)
	}
	h, err := repo.Storer.SetEncodedObject(obj)
	if err != nil {
		t.Fatal(err)
	}
	return h
}
```

