// AggregateRange — see godoc in plan.
func AggregateRange(sessions []ActivitySession, from, to time.Time) ActivityRangeSummary {
	sum := ActivityRangeSummary{
		From:            from,
		To:              to,
		LabelCounts:     map[string]int{},
		FocusAreaCounts: map[string]int{},
		AgentCounts:     map[string]int{},
		ModelCounts:     map[string]int{},
		ToolTimeMs:      map[string]int64{},
	}
	repos := map[string]bool{}
	activeDays := map[string]bool{}
	for _, s := range sessions {
		sum.Sessions++
		if s.Repo != "" {
			repos[s.Repo] = true
		}
		sum.LinkedCommits += len(s.LinkedCommits)
		for _, a := range s.AgentsUsed {
			sum.AgentCounts[a]++
		}
		for _, m := range s.ModelsUsed {
			sum.ModelCounts[m]++
		}
		for _, cp := range s.Checkpoints {
			if cp.CreatedAt.Before(from) || cp.CreatedAt.After(to) {
				continue
			}
			sum.Checkpoints++
			if cp.IsTask {
				sum.TaskCheckpoints++
			}
			activeDays[cp.CreatedAt.Format("2006-01-02")] = true
			for _, lbl := range cp.Labels {
				sum.LabelCounts[lbl]++
			}
			for _, fa := range cp.FocusAreas {
				sum.FocusAreaCounts[fa]++
			}
		}
	}
	for r := range repos {
		sum.ReposTouched = append(sum.ReposTouched, r)
	}
	sort.Strings(sum.ReposTouched)
	sum.ActiveDays = len(activeDays)
	return sum
}

// LabelCounts — see godoc in plan.
func LabelCounts(sessions []ActivitySession) map[string]int {
	out := map[string]int{}
	for _, s := range sessions {
		for _, cp := range s.Checkpoints {
			for _, lbl := range cp.Labels {
				out[lbl]++
			}
		}
	}
	return out
}

// DominantLabel — see godoc in plan.
func DominantLabel(counts map[string]int) (string, bool) {
	total := 0
	for _, c := range counts {
		total += c
	}
	if total == 0 {
		return "", false
	}
	type kv struct {
		k string
		v int
	}
	all := make([]kv, 0, len(counts))
	for k, v := range counts {
		all = append(all, kv{k, v})
	}
	sort.Slice(all, func(i, j int) bool { return all[i].v > all[j].v })
	topShare := float64(all[0].v) / float64(total)
	if topShare < 0.55 {
		return "", false
	}
	if len(all) == 1 {
		return all[0].k, true
	}
	runnerShare := float64(all[1].v) / float64(total)
	if topShare-runnerShare < 0.15 {
		return "", false
	}
	return all[0].k, true
}

// AggregateByDay — see godoc in plan.
func AggregateByDay(sessions []ActivitySession, from, to time.Time, tz *time.Location) []ActivityDay {
	if tz == nil {
		tz = time.UTC
	}
	startDay := dayStart(from, tz)
	endDay := dayStart(to, tz)
	days := int(endDay.Sub(startDay).Hours()/24) + 1
	if days < 1 {
		return nil
	}
	out := make([]ActivityDay, days)
	byDay := map[string]*ActivityDay{}
	for i := 0; i < days; i++ {
		d := startDay.AddDate(0, 0, i)
		out[i] = ActivityDay{
			Date:            d,
			LabelCounts:     map[string]int{},
			FocusAreaCounts: map[string]int{},
			ToolTimeMs:      map[string]int64{},
		}
		byDay[d.Format("2006-01-02")] = &out[i]
	}
	for _, s := range sessions {
		for _, cp := range s.Checkpoints {
			key := dayStart(cp.CreatedAt, tz).Format("2006-01-02")
			d, ok := byDay[key]
			if !ok {
				continue
			}
			d.Checkpoints++
			if cp.IsTask {
				d.TaskCheckpoints++
			}
			if cp.LinkedCommit != "" {
				d.LinkedCommits++
			}
			for _, lbl := range cp.Labels {
				d.LabelCounts[lbl]++
			}
			for _, fa := range cp.FocusAreas {
				d.FocusAreaCounts[fa]++
			}
		}
	}
	return out
}

// AggregateByAgent — see godoc in plan.
func AggregateByAgent(sessions []ActivitySession) []ActivityAgentSummary {
	type bucket struct {
		summary ActivityAgentSummary
		linked  int
	}
	m := map[string]*bucket{}
	for _, s := range sessions {
		for _, a := range s.AgentsUsed {
			b, ok := m[a]
			if !ok {
				b = &bucket{summary: ActivityAgentSummary{
					Agent:       a,
					LabelCounts: map[string]int{},
					ToolTimeMs:  map[string]int64{},
				}}
				m[a] = b
			}
			b.summary.Sessions++
			for _, cp := range s.Checkpoints {
				b.summary.Checkpoints++
				if cp.LinkedCommit != "" {
					b.linked++
				}
				for _, lbl := range cp.Labels {
					b.summary.LabelCounts[lbl]++
				}
			}
		}
	}
	out := make([]ActivityAgentSummary, 0, len(m))
	for _, b := range m {
		if b.summary.Checkpoints > 0 {
			b.summary.LinkedRate = float64(b.linked) / float64(b.summary.Checkpoints)
			b.summary.CheckpointDensity = float64(b.summary.Checkpoints) / float64(b.summary.Sessions)
		}
		out = append(out, b.summary)
	}
	sort.Slice(out, func(i, j int) bool {
		if out[i].Sessions != out[j].Sessions {
			return out[i].Sessions > out[j].Sessions
		}
		return out[i].Agent < out[j].Agent
	})
	return out
}

// AggregateByRepo — see godoc in plan.
func AggregateByRepo(sessions []ActivitySession) []ActivityRepoSummary {
	type bucket struct {
		summary ActivityRepoSummary
		linked  int
	}
	m := map[string]*bucket{}
	for _, s := range sessions {
		if s.Repo == "" {
			continue
		}
		b, ok := m[s.Repo]
		if !ok {
			b = &bucket{summary: ActivityRepoSummary{
				Repo:        s.Repo,
				LabelCounts: map[string]int{},
			}}
			m[s.Repo] = b
		}
		b.summary.Sessions++
		b.summary.LinkedCommits += len(s.LinkedCommits)
		for _, cp := range s.Checkpoints {
			b.summary.Checkpoints++
			if cp.LinkedCommit != "" {
				b.linked++
			}
			for _, lbl := range cp.Labels {
				b.summary.LabelCounts[lbl]++
			}
		}
	}
	out := make([]ActivityRepoSummary, 0, len(m))
	for _, b := range m {
		if b.summary.Checkpoints > 0 {
			b.summary.LinkedRate = float64(b.linked) / float64(b.summary.Checkpoints)
		}
		out = append(out, b.summary)
	}
	sort.Slice(out, func(i, j int) bool {
		if out[i].Sessions != out[j].Sessions {
			return out[i].Sessions > out[j].Sessions
		}
		return out[i].Repo < out[j].Repo
	})
	return out
}
