Add `writeCommittedCheckpoint` to `testutil_test.go`. We bypass `checkpoint.GitStore.WriteCommitted` (which requires full `WriteCommittedOptions` including a real redacted transcript) and write the sharded metadata tree directly via go-git plumbing.

**Data shape required (verified in `strategy/common.go:122-229`):**

`strategy.ListCheckpoints` reads TWO files per checkpoint:

1. **Root:** `<id[:2]>/<id[2:]>/metadata.json` — decoded as `checkpointSummaryLite` (`strategy/common.go:445-450`). Must contain `checkpoints_count`, `files_touched`, and `sessions[]` where each element has a `metadata` field pointing to the session-level metadata file.
2. **Per-session:** `<id[:2]>/<id[2:]>/0/metadata.json` — decoded as `sessionMetadataLite` (`strategy/common.go:435-441`). Must contain `session_id`, `agent`, `created_at`, optionally `is_task` and `tool_use_id`.

The `sessions[i].metadata` path in the root is absolute with a leading `/` (`strategy/common.go:200-202` strips it before reading). So we emit e.g. `"/aa/11bb22cc33/0/metadata.json"`.

```go
// testutil_test.go additions
import (
	"encoding/json"
	"os/exec"

	gogit "github.com/go-git/go-git/v6"
	"github.com/go-git/go-git/v6/plumbing"
	"github.com/go-git/go-git/v6/plumbing/filemode"
	"github.com/go-git/go-git/v6/plumbing/object"

	"github.com/entireio/cli/cmd/entire/cli/checkpoint"
	"github.com/entireio/cli/cmd/entire/cli/checkpoint/id"
)

type committedFixture struct {
	ID        string // 12-hex-char checkpoint ID
	SessionID string
	Agent     string // e.g. "Claude Code"; optional
	CreatedAt time.Time
	Files     []string
}

// writeCommittedCheckpoint writes a valid two-file metadata pair onto the
// entire/checkpoints/v1 branch: root metadata.json (CheckpointSummary shape)
// and 0/metadata.json (sessionMetadataLite shape). This is what
// strategy.ListCheckpoints reads; any deviation from this shape will cause
// the loader to silently skip the checkpoint.
func writeCommittedCheckpoint(t *testing.T, repoRoot string, f committedFixture) {
	t.Helper()
	repo, err := gogit.PlainOpen(repoRoot)
	if err != nil {
		t.Fatalf("open repo: %v", err)
	}

	// --- 1. Build session-level metadata blob (0/metadata.json). ---
	// Fields mirror sessionMetadataLite in strategy/common.go:435-441.
	sessionMeta := map[string]any{
		"session_id": f.SessionID,
		"created_at": f.CreatedAt.Format(time.RFC3339Nano),
	}
	if f.Agent != "" {
		sessionMeta["agent"] = f.Agent
	}
	sessionBody, err := json.MarshalIndent(sessionMeta, "", "  ")
	if err != nil {
		t.Fatal(err)
	}
	sessionBlobHash := writeBlob(t, repo, sessionBody)

	// --- 2. Build root metadata blob (metadata.json). ---
	// Fields mirror checkpointSummaryLite in strategy/common.go:445-450.
	// Session paths are absolute (leading "/"): "/<id[:2]>/<id[2:]>/0/metadata.json".
	summary := checkpoint.CheckpointSummary{
		CheckpointID:     id.CheckpointID(f.ID),
		Strategy:         "manual-commit",
		CheckpointsCount: 1,
		FilesTouched:     f.Files,
		Sessions: []checkpoint.SessionFilePaths{
			{Metadata: "/" + f.ID[:2] + "/" + f.ID[2:] + "/0/metadata.json"},
		},
	}
	summaryBody, err := json.MarshalIndent(summary, "", "  ")
	if err != nil {
		t.Fatal(err)
	}
	summaryBlobHash := writeBlob(t, repo, summaryBody)

	// --- 3. Build tree for 0/ (contains session metadata.json). ---
	sessionDirHash := writeTree(t, repo, []object.TreeEntry{
		{Name: "metadata.json", Mode: filemode.Regular, Hash: sessionBlobHash},
	})

	// --- 4. Build tree for <id[2:]>/ (contains root metadata.json + 0/). ---
	cpDirHash := writeTree(t, repo, []object.TreeEntry{
		{Name: "metadata.json", Mode: filemode.Regular, Hash: summaryBlobHash},
		{Name: "0", Mode: filemode.Dir, Hash: sessionDirHash},
	})

	// --- 5. Build tree for <id[:2]>/ (contains cp dir). ---
	shardDirHash := writeTree(t, repo, []object.TreeEntry{
		{Name: f.ID[2:], Mode: filemode.Dir, Hash: cpDirHash},
	})

	// --- 6. Build root tree. ---
	rootHash := writeTree(t, repo, []object.TreeEntry{
		{Name: f.ID[:2], Mode: filemode.Dir, Hash: shardDirHash},
	})

	// --- 7. Commit on entire/checkpoints/v1. ---
	commitHash := writeCommit(t, repo, rootHash, f.CreatedAt, "Checkpoint: "+f.ID)

	// --- 8. Point the branch ref at the new commit. ---
	cmd := exec.Command("git", "update-ref", "refs/heads/entire/checkpoints/v1", commitHash.String())
	cmd.Dir = repoRoot
	if out, err := cmd.CombinedOutput(); err != nil {
		t.Fatalf("update-ref: %v\n%s", err, out)
	}
}

// writeBlob encodes bytes into a git blob and returns its hash.
// Uses repo.Storer.NewEncodedObject() — same pattern as production in
// checkpoint/committed.go:1468-1492.
func writeBlob(t *testing.T, repo *gogit.Repository, data []byte) plumbing.Hash {
	t.Helper()
	obj := repo.Storer.NewEncodedObject()
	obj.SetType(plumbing.BlobObject)
	w, err := obj.Writer()
	if err != nil {
		t.Fatal(err)
	}
	if _, err := w.Write(data); err != nil {
		t.Fatal(err)
	}
	if err := w.Close(); err != nil {
		t.Fatal(err)
	}
	h, err := repo.Storer.SetEncodedObject(obj)
	if err != nil {
		t.Fatal(err)
	}
	return h
}

// writeTree builds an object.Tree from entries and stores it, returning its hash.
func writeTree(t *testing.T, repo *gogit.Repository, entries []object.TreeEntry) plumbing.Hash {
	t.Helper()
	tree := object.Tree{Entries: entries}
	obj := repo.Storer.NewEncodedObject()
	if err := tree.Encode(obj); err != nil {
		t.Fatal(err)
	}
	h, err := repo.Storer.SetEncodedObject(obj)
	if err != nil {
		t.Fatal(err)
	}
	return h
}

// writeCommit builds an orphan-style commit (no parent) at the given tree.
func writeCommit(t *testing.T, repo *gogit.Repository, tree plumbing.Hash, when time.Time, msg string) plumbing.Hash {
	t.Helper()
	sig := object.Signature{Name: "test", Email: "test@example.com", When: when}
	commit := object.Commit{
		Author:    sig,
		Committer: sig,
		Message:   msg,
		TreeHash:  tree,
	}
	obj := repo.Storer.NewEncodedObject()
	if err := commit.Encode(obj); err != nil {
		t.Fatal(err)
	}
	h, err := repo.Storer.SetEncodedObject(obj)
	if err != nil {
		t.Fatal(err)
	}
	return h
}
