// buildEnricher returns an Enricher if the user is logged in. Returns
// nil when no token is present — callers treat that as "enrichment off."
func buildEnricher(ctx context.Context, worktreeRoot string, insecure bool) *Enricher {
	// Reuse the existing authenticated-client pattern from trail_cmd.go.
	token, err := auth.LookupCurrentToken()
	if err != nil || token == "" {
		return nil
	}
	client := api.NewClient(token)
	gitCommonDir, err := strategy.GetGitCommonDir(ctx)
	if err != nil {
		return NewEnricher(client, nil)
	}
	cache, err := NewAnalysisCache(gitCommonDir)
	if err != nil {
		return NewEnricher(client, nil)
	}
	return NewEnricher(client, cache)
}

// enrichSessionsInPlace mutates the checkpoints of each session, setting
// Labels and ToolProfile from the api when available. Each checkpoint
// fetches independently; failures don't block others.
func enrichSessionsInPlace(ctx context.Context, e *Enricher, sessions []ActivitySession) {
	for si := range sessions {
		for ci := range sessions[si].Checkpoints {
			enriched, _ := e.EnrichCheckpoint(ctx, sessions[si].Checkpoints[ci])
			sessions[si].Checkpoints[ci] = enriched
		}
		// Roll session-level Labels up from its checkpoints.
		sessions[si].Labels = rollupLabels(sessions[si].Checkpoints)
		if sessionHasServerData(sessions[si].Checkpoints) {
			sessions[si].Source = SourceMixed
		}
	}
}

func rollupLabels(cps []ActivityCheckpoint) []string {
	seen := map[string]bool{}
	out := []string{}
	for _, cp := range cps {
		for _, l := range cp.Labels {
			if seen[l] {
				continue
			}
			seen[l] = true
			out = append(out, l)
		}
	}
	return out
}

func sessionHasServerData(cps []ActivityCheckpoint) bool {
	for _, cp := range cps {
		if cp.Source == SourceMixed || cp.Source == SourceServer {
			return true
		}
	}
	return false
}
