```go
package activity

import (
	"bufio"
	"encoding/json"
	"io"
	"time"
)

// DeriveToolTime walks a JSONL transcript and returns a ToolProfile with
// per-category counts and durations. Duration semantics: "time between
// the start of this tool_use and the start of the next tool_use" (or
// turn end). This is NOT pure tool execution time — it includes agent
// thinking and response time. Label this "Time between tool calls"
// when rendering, not "execution time."
//
// The virtual `conversation` category captures time between tool_result
// and next tool_use where the assistant produced text in the gap.
//
// The virtual `commit` category catches bash commands starting with
// `git commit` or `git push`.
//
// Input format matches cmd/entire/cli/transcript/types.go (Claude Code
// and Cursor share the Line shape).
func DeriveToolTime(r io.Reader) (*ToolProfile, error) {
	profile := &ToolProfile{Categories: map[string]ToolCategoryMetrics{}}

	type pending struct {
		category string
		at       time.Time
	}
	var lastToolUse *pending
	var lastToolResultAt *time.Time
	var assistantTextSinceResult bool

	scanner := bufio.NewScanner(r)
	scanner.Buffer(make([]byte, 1<<20), 1<<24) // 16MiB line cap for giant tool outputs.

	type line struct {
		Type      string    `json:"type"`
		Timestamp time.Time `json:"timestamp"`
		Message   struct {
			Content []struct {
				Type    string          `json:"type"`
				Name    string          `json:"name,omitempty"`
				Text    string          `json:"text,omitempty"`
				Input   json.RawMessage `json:"input,omitempty"`
			} `json:"content"`
		} `json:"message"`
	}

	for scanner.Scan() {
		var l line
		if err := json.Unmarshal(scanner.Bytes(), &l); err != nil {
			continue // skip malformed lines
		}
		for _, c := range l.Message.Content {
			switch c.Type {
			case "tool_use":
				cmd := bashCommandFromInput(c.Input)
				category := CategorizeTool(c.Name, cmd)

				// Close the previous tool_use's duration.
				if lastToolUse != nil {
					d := l.Timestamp.Sub(lastToolUse.at)
					if d > 0 {
						addDuration(profile, lastToolUse.category, d)
					}
				}
				// Maybe credit conversation time between prior tool_result
				// and this tool_use if assistant produced text in the gap.
				if lastToolResultAt != nil && assistantTextSinceResult {
					d := l.Timestamp.Sub(*lastToolResultAt)
					if d > 0 {
						addDuration(profile, CategoryConversation, d)
					}
				}
				incrementCount(profile, category)
				lastToolUse = &pending{category: category, at: l.Timestamp}
				lastToolResultAt = nil
				assistantTextSinceResult = false
			case "tool_result":
				ts := l.Timestamp
				lastToolResultAt = &ts
				assistantTextSinceResult = false
			case "text":
				if lastToolResultAt != nil {
					assistantTextSinceResult = true
				}
			}
		}
	}
	if err := scanner.Err(); err != nil {
		return profile, err
	}
	return profile, nil
}

func bashCommandFromInput(raw json.RawMessage) string {
	var v struct {
		Command string `json:"command,omitempty"`
	}
	_ = json.Unmarshal(raw, &v)
	return v.Command
}

func incrementCount(p *ToolProfile, category string) {
	m := p.Categories[category]
	m.Count++
	p.Categories[category] = m
	p.Total.Count++
}

func addDuration(p *ToolProfile, category string, d time.Duration) {
	m := p.Categories[category]
	m.DurationMs += d.Milliseconds()
	p.Categories[category] = m
	p.Total.DurationMs += d.Milliseconds()
}
```

