// Heatmap ramp glyphs + matching 256-color IDs (dark → bright green).
var heatmapRamp = [5]struct {
	glyph string
	color string
}{
	{"░", "237"}, // empty / barely-any
	{"▒", "22"},  // low
	{"▓", "28"},  // mid
	{"▓", "34"},  // high
	{"█", "46"},  // peak
}

// HeatmapCell renders one cell for the given intensity tier (0..4).
// Falls back to glyph-only (no color) when NO_COLOR is set.
func HeatmapCell(intensity int) string {
	if intensity < 0 {
		intensity = 0
	}
	if intensity > 4 {
		intensity = 4
	}
	cell := heatmapRamp[intensity]
	if !shouldUseColor(colorDetectWriter()) {
		return cell.glyph
	}
	return lipgloss.NewStyle().Foreground(lipgloss.Color(cell.color)).Render(cell.glyph)
}

// Intra-day strip glyphs (1/8 to full block).
var intraDayGlyphs = []rune{' ', '▁', '▂', '▃', '▄', '▅', '▆', '▇', '█'}

// IntraDayStrip renders a 24-hour activity strip using per-hour counts.
// Each hour gets one glyph scaled to the peak. Uses amber gradient when
// color is enabled.
func IntraDayStrip(counts [24]int) string {
	max := 0
	for _, c := range counts {
		if c > max {
			max = c
		}
	}
	var out []string
	for _, c := range counts {
		idx := 0
		if max > 0 {
			idx = (c * (len(intraDayGlyphs) - 1)) / max
		}
		glyph := string(intraDayGlyphs[idx])
		if shouldUseColor(colorDetectWriter()) && idx > 0 {
			// Amber fade: brighter for higher.
			glyph = lipgloss.NewStyle().Foreground(lipgloss.Color("214")).Render(glyph)
		}
		out = append(out, glyph)
	}
	return strings.Join(out, " ")
}

// GradientBar renders a horizontal bar of the given width, coloring each
// filled cell with a lerp from teal → amber → orange (CodeBurn-style).
// Empty cells use glyph ░ in dim gray.
func GradientBar(value, max float64, width int) string {
	if width <= 0 {
		return ""
	}
	if max <= 0 {
		return strings.Repeat("░", width)
	}
	filled := int((value / max) * float64(width))
	if filled > width {
		filled = width
	}
	if filled < 0 {
		filled = 0
	}
	if !shouldUseColor(colorDetectWriter()) {
		return strings.Repeat("█", filled) + strings.Repeat("░", width-filled)
	}
	var b strings.Builder
	for i := 0; i < filled; i++ {
		pct := float64(i) / float64(width)
		b.WriteString(lipgloss.NewStyle().Foreground(lipgloss.Color(gradientColor(pct))).Render("█"))
	}
	for i := filled; i < width; i++ {
		b.WriteString(lipgloss.NewStyle().Foreground(lipgloss.Color("237")).Render("░"))
	}
	return b.String()
}

// gradientColor lerps over teal → amber → orange as pct goes 0 → 1.
// Returns a 256-color ID string.
func gradientColor(pct float64) string {
	// Simple 3-stop palette mapped to 256-color IDs.
	switch {
	case pct < 0.33:
		return "43" // teal
	case pct < 0.66:
		return "214" // amber
	default:
		return "202" // orange
	}
}

// colorDetectWriter returns stdout for color detection purposes when the
// caller doesn't have a specific writer. Used by the "pure" render
// helpers above that don't take a writer.
func colorDetectWriter() io.Writer { return os.Stdout }
