package activity

import (
	"fmt"
	"io"
	"sort"
	"strings"
	"time"
)

// Tab identifiers — used across static and TUI renderers.
type Tab int

const (
	TabToday Tab = iota
	TabRange
	TabHistory
	TabAgents
	TabRepos
	TabReport
)

// StaticRenderOpts controls the static renderer.
type StaticRenderOpts struct {
	Tab  Tab
	Repo string
	Now  time.Time
}

// RenderStatic writes the non-TTY output for a single tab.
func RenderStatic(w io.Writer, act *Activity, opts StaticRenderOpts) error {
	fmt.Fprintln(w, "Entire Activity")
	fmt.Fprintln(w)
	switch opts.Tab {
	case TabToday:
		return renderStaticToday(w, act, opts)
	case TabRange:
		return renderStaticRange(w, act, opts)
	case TabAgents:
		return renderStaticAgents(w, act, opts)
	case TabRepos:
		return renderStaticRepos(w, act, opts)
	case TabHistory:
		return renderStaticHistory(w, act, opts)
	case TabReport:
		return renderStaticReport(w, act, opts)
	}
	return fmt.Errorf("activity: unknown tab %d", opts.Tab)
}

func renderStaticToday(w io.Writer, act *Activity, opts StaticRenderOpts) error {
	fmt.Fprintf(w, "Today — %s\n", opts.Now.Format("Mon Jan 02 2006"))
	fmt.Fprintf(w, "Repo: %s\n\n", opts.Repo)

	// Summary.
	totalSessions := 0
	totalCheckpoints := 0
	totalLinked := 0
	var spans []float64
	for _, s := range act.Sessions {
		totalSessions++
		totalCheckpoints += len(s.Checkpoints)
		totalLinked += len(s.LinkedCommits)
		if sp := s.SpanMinutes(); sp > 0 {
			spans = append(spans, sp)
		}
	}
	totalSpan := 0.0
	for _, sp := range spans {
		totalSpan += sp
	}
	fmt.Fprintf(w, "Summary\n")
	fmt.Fprintf(w, "  Sessions: %d\n", totalSessions)
	fmt.Fprintf(w, "  Checkpoints: %d\n", totalCheckpoints)
	fmt.Fprintf(w, "  Linked Commits: %d\n", totalLinked)
	fmt.Fprintf(w, "  Span: %s\n", formatMinutes(totalSpan))
	fmt.Fprintln(w)

	// Modes.
	labelCounts := LabelCounts(act.Sessions)
	if len(labelCounts) > 0 {
		fmt.Fprintln(w, "Modes")
		printMap(w, labelCounts)
		fmt.Fprintln(w)
	}

	// Recent sessions.
	if len(act.Sessions) > 0 {
		fmt.Fprintln(w, "Recent Sessions")
		sorted := append([]ActivitySession(nil), act.Sessions...)
		sort.Slice(sorted, func(i, j int) bool {
			return sorted[i].StartedAt.After(sorted[j].StartedAt)
		})
