	labels := strings.Join(s.Labels, ",")
	focus := strings.Join(s.FocusAreas, ", ")
	badges := strings.Join(s.Badges, " ")
	fmt.Fprintf(w, "  %s — %s — %s — %s\n", timeStr, labels, focus, badges)
}

func printMap(w io.Writer, m map[string]int) {
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sort.Slice(keys, func(i, j int) bool { return m[keys[i]] > m[keys[j]] })
	for _, k := range keys {
		fmt.Fprintf(w, "  %s: %d\n", k, m[k])
	}
}

func formatMinutes(minutes float64) string {
	if minutes <= 0 {
		return "0m"
	}
	h := int(minutes) / 60
	m := int(minutes) % 60
	if h > 0 {
		return fmt.Sprintf("%dh %02dm", h, m)
	}
	return fmt.Sprintf("%dm", m)
}
