```go
// RenderJSON writes --json output. schema_version is locked at "v1" —
// never change without bumping the major. Downstream tools gate on this.
func RenderJSON(w io.Writer, act *Activity, opts StaticRenderOpts) error {
	out := jsonEnvelope{
		SchemaVersion: "v1",
		GeneratedAt:   opts.Now,
		Scope: jsonScope{
			Repo: opts.Repo,
			From: opts.Now.Truncate(24 * time.Hour),
			To:   opts.Now,
		},
		Sessions:   toJSONSessions(act.Sessions),
		Aggregates: toJSONAggregates(act),
	}
	enc := json.NewEncoder(w)
	enc.SetIndent("", "  ")
	return enc.Encode(out)
}

type jsonEnvelope struct {
	SchemaVersion string          `json:"schema_version"`
	GeneratedAt   time.Time       `json:"generated_at"`
	Scope         jsonScope       `json:"scope"`
	Sessions      []jsonSession   `json:"sessions"`
	Aggregates    jsonAggregates  `json:"aggregates"`
}
```

Define sub-structures (`jsonSession`, `jsonAggregates`, etc.) with explicit JSON tags. Do NOT serialize raw projection types — the JSON shape is a public contract and should not leak internal struct field names.

