```go
package activity

import (
	tea "github.com/charmbracelet/bubbletea"
)

// TUIModel is the bubbletea state for the activity TUI.
type TUIModel struct {
	activity *Activity
	repo     string
	tab      Tab
	styles   activityStyles
	width    int
	height   int
	drilldown *ActivitySession // non-nil when drill-down is open
}

func NewTUIModel(act *Activity, repo string) TUIModel {
	return TUIModel{activity: act, repo: repo, tab: TabToday}
}

func (m TUIModel) Init() tea.Cmd { return nil }

func (m TUIModel) CurrentTab() Tab { return m.tab }

func (m TUIModel) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch msg := msg.(type) {
	case tea.KeyMsg:
		return m.handleKey(msg)
	case tea.WindowSizeMsg:
		m.width = msg.Width
		m.height = msg.Height
	}
	return m, nil
}

func (m TUIModel) handleKey(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	switch msg.Type {
	case tea.KeyTab:
		m.tab = Tab((int(m.tab) + 1) % 6)
		return m, nil
	case tea.KeyShiftTab:
		m.tab = Tab((int(m.tab) + 5) % 6)
		return m, nil
	case tea.KeyEsc:
		m.drilldown = nil
		return m, nil
	}
	if len(msg.Runes) == 1 {
		switch msg.Runes[0] {
		case 'q':
			return m, tea.Quit
		case '1':
			m.tab = TabToday
		case '2':
			m.tab = TabRange
		case '3':
			m.tab = TabHistory
		case '4':
			m.tab = TabAgents
		case '5':
			m.tab = TabRepos
		case '6':
			m.tab = TabReport
		}
	}
	return m, nil
}

func (m TUIModel) View() string {
	// Implementation lands in Task 26 (panels).
	return "activity tui — tab " + tabName(m.tab)
}

func tabName(t Tab) string {
	switch t {
	case TabToday:
		return "today"
	case TabRange:
		return "range"
	case TabHistory:
		return "history"
	case TabAgents:
		return "agents"
	case TabRepos:
		return "repos"
	case TabReport:
		return "report"
	}
	return "?"
}
```

