Example `activity_today.go`:

```go
func newActivityTodayCmd() *cobra.Command {
	return &cobra.Command{
		Use:   "today",
		Short: "Show today's agent activity",
		RunE: func(cmd *cobra.Command, _ []string) error {
			return runActivityToday(cmd, parseFlags(cmd))
		},
	}
}

func runActivityToday(cmd *cobra.Command, f activityFlags) error {
	ctx := cmd.Context()
	act, err := activity.LoadActivity(ctx, buildLoadOpts(f))
	if err != nil {
		return err
	}
	if f.json {
		return activity.RenderJSON(cmd.OutOrStdout(), act, activityStaticOpts(activity.TabToday, f))
	}
	if isTerminalWriter(cmd.OutOrStdout()) && os.Getenv("ACCESSIBLE") == "" {
		return runTUI(cmd, act, activity.TabToday, f)
	}
	return activity.RenderStatic(cmd.OutOrStdout(), act, activityStaticOpts(activity.TabToday, f))
}
```

`runTUI` is a small helper that launches `bubbletea.NewProgram(activity.NewTUIModel(act, repo)).Run()`.

