// TokenProvider returns an auth token or empty string when the user is
// not logged in. Default production implementation reads from the system
// keyring via auth.LookupCurrentToken; integration tests inject a stub.
type TokenProvider func() (string, error)

// defaultTokenProvider reads from the OS keyring. Used when LoadOpts.TokenProvider is nil.
func defaultTokenProvider() (string, error) { return auth.LookupCurrentToken() }

// buildEnricher returns an Enricher if a token is available. Returns
// nil when no token — callers treat that as "enrichment off."
func buildEnricher(ctx context.Context, opts LoadOpts) *Enricher {
	provider := opts.TokenProvider
	if provider == nil {
		provider = defaultTokenProvider
	}
	token, err := provider()
	if err != nil || token == "" {
		return nil
	}
	client := api.NewClient(token)
	gitCommonDir, err := strategy.GetGitCommonDir(ctx)
	if err != nil {
		return NewEnricher(client, nil)
	}
	cache, err := NewAnalysisCache(gitCommonDir)
	if err != nil {
		return NewEnricher(client, nil)
	}
	return NewEnricher(client, cache)
}

