// DataSource tags where a projected value came from.
type DataSource int

const (
	SourceLocal DataSource = iota
	SourceServer
	SourceMixed
)

// String returns the lower-case name used in chrome footers and JSON output.
func (d DataSource) String() string {
	switch d {
	case SourceServer:
		return "server"
	case SourceMixed:
		return "mixed"
	default:
		return "local"
	}
}

// TokenProvider is injected by callers for testing; production uses
// auth.LookupCurrentToken via defaultTokenProvider (see enrich.go).
// Declared here so LoadOpts can reference it without a cross-file cycle.
type TokenProvider func() (string, error)

// ActivitySession is a read-only projection of a session for activity views.
// Built by load.go from session.State + per-session checkpoint rollups,
// optionally enriched with api-fetched labels. Never persisted.
type ActivitySession struct {
	Repo            string
	SessionID       string
	Branch          string
	WorktreeID      string
	WorktreePath    string
	BaseCommit      string

	StartedAt       time.Time
	EndedAt         *time.Time
	LastInteraction time.Time
	Phase           session.Phase

	Checkpoints     []ActivityCheckpoint
	FilesTouched    []string
	LinkedCommits   []string // SHAs whose message contains this session's Entire-Checkpoint trailers

	AgentsUsed      []string
	ModelsUsed      []string

	FocusAreas      []string // tier 2; computed from FilesTouched
	Labels          []string // tier 3; empty when offline or not yet analyzed
	Badges          []string // tier 2; deterministic local facts
	TokenUsage      *agent.TokenUsage

	// ToolProfile is the session-level tool-time breakdown. Populated from
	// local transcripts for active sessions and rolled up from per-checkpoint
	// server data for committed ones. nil when no data is available.
	ToolProfile     *ToolProfile

	IsActive        bool
	IsResumable     bool

	Source          DataSource
}

// SpanMinutes returns the honest first-to-last checkpoint timestamp span
// in minutes. Returns 0 when fewer than two checkpoints exist.
func (a ActivitySession) SpanMinutes() float64 {
	if len(a.Checkpoints) < 2 {
		return 0
	}
	first := a.Checkpoints[0].CreatedAt
	last := a.Checkpoints[0].CreatedAt
	for _, cp := range a.Checkpoints[1:] {
		if cp.CreatedAt.Before(first) {
			first = cp.CreatedAt
		}
		if cp.CreatedAt.After(last) {
			last = cp.CreatedAt
		}
	}
	return last.Sub(first).Minutes()
}

// ActivityCheckpoint is a projection of one committed checkpoint.
type ActivityCheckpoint struct {
	Repo         string
	SessionID    string
	ID           id.CheckpointID
	CreatedAt    time.Time
	IsTask       bool
	ToolUseID    string
	Agent        string
	Model        string
	FilesTouched []string
	FocusAreas   []string
	LinkedCommit string
	TokenUsage   *agent.TokenUsage
	TurnID       string
	Labels       []string // tier 3
	ToolProfile  *ToolProfile
	Badges       []string
	Source       DataSource
}

// ToolProfile mirrors api/src/types.ts ToolProfile but with optional
// per-category durations. DurationMs is 0 when the server hasn't
// provided it yet.
type ToolProfile struct {
	Categories map[string]ToolCategoryMetrics `json:"categories"`
	Total      ToolCategoryMetrics            `json:"total"`
}

// ToolCategoryMetrics holds count and optional duration for a tool category.
type ToolCategoryMetrics struct {
	Count      int   `json:"count"`
	DurationMs int64 `json:"duration_ms,omitempty"`
}

// ActivityDay is a per-day rollup shown in range/history/heatmap views.
type ActivityDay struct {
	Date             time.Time
	Repos            []string
	Sessions         int
	Checkpoints      int
	TaskCheckpoints  int
	LinkedCommits    int
	TokenTotal       int
	LabelCounts      map[string]int
	FocusAreaCounts  map[string]int
	ResumeCount      int
	ToolTimeMs       map[string]int64 // per-category duration
