## Issue 2 (Important): non-atomic write

Replace `os.WriteFile(c.path(checkpointID), data, 0o600)` with a temp-file-then-rename pattern so a crash mid-write doesn't leave a partial file:

```go
func (c *AnalysisCache) Put(checkpointID string, resp *CheckpointAnalysisResponse) error {
	if !isValidKey(checkpointID) {
		return fmt.Errorf("activity cache: invalid checkpoint id %q", checkpointID)
	}
	c.mu.Lock()
	defer c.mu.Unlock()
	if err := os.MkdirAll(c.dir, 0o750); err != nil {
		return fmt.Errorf("activity cache mkdir: %w", err)
	}
	data, err := json.Marshal(resp)
	if err != nil {
		return fmt.Errorf("activity cache marshal: %w", err)
	}
	target := c.path(checkpointID)
	tmp, err := os.CreateTemp(c.dir, ".tmp-*.json")
	if err != nil {
		return fmt.Errorf("activity cache tempfile: %w", err)
	}
	tmpPath := tmp.Name()
	if _, err := tmp.Write(data); err != nil {
		_ = tmp.Close()
		_ = os.Remove(tmpPath)
		return fmt.Errorf("activity cache write: %w", err)
	}
	if err := tmp.Close(); err != nil {
		_ = os.Remove(tmpPath)
		return fmt.Errorf("activity cache tempfile close: %w", err)
	}
	if err := os.Chmod(tmpPath, 0o600); err != nil {
		_ = os.Remove(tmpPath)
		return fmt.Errorf("activity cache chmod: %w", err)
	}
	if err := os.Rename(tmpPath, target); err != nil {
		_ = os.Remove(tmpPath)
		return fmt.Errorf("activity cache rename: %w", err)
	}
	return nil
}
```

